import{a,_ as r}from"./chunks/single_macro_morph.JTlb24F-.js";import{_ as s,C as h,o as i,c as g,a3 as p,E as l,w as d,j as t,a as o}from"./chunks/framework.mn-nY1d4.js";const c="/versions/v0.19.32/screens/snapshots/knob_bank_morph.png",m="/versions/v0.19.32/screens/macros/macro_morph_amount.png",M=JSON.parse('{"title":"Morph","description":"","frontmatter":{},"headers":[],"relativePath":"snapshots/morph.md","filePath":"snapshots/morph.md"}'),u={name:"snapshots/morph.md"};function f(b,e,k,w,y,A){const n=h("ManualRelated");return i(),g("div",null,[e[1]||(e[1]=p('<h1 id="morph" tabindex="-1">Morph <a class="header-anchor" href="#morph" aria-label="Permalink to &quot;Morph&quot;">​</a></h1><p>Occupied <strong>Select</strong> on a snapshot pad glides from <strong>what you are hearing</strong> to that pad. <strong>FADE TIME</strong> on that bank’s <strong>pencil</strong> is the glide length in musical time at project BPM. When fade is <strong>OFF</strong>, Select is instant. Arrange <strong>FADE TIME</strong> is only the song playhead.</p><p>MIDI, a mapped slot, a macro, and the Arrange <strong>playhead</strong> use the same glide. There are no <strong>SET MORPH A</strong> / <strong>SET MORPH B</strong> marks and no <strong>END MORPH</strong> row. Pads do not show A/B marks.</p><h2 id="start-a-morph" tabindex="-1">Start a morph <a class="header-anchor" href="#start-a-morph" aria-label="Permalink to &quot;Start a morph&quot;">​</a></h2><p>On any <strong>4×8</strong> (<a href="./knob-bank">knobs</a>, <a href="./lfo-bank">LFOs</a>, <a href="./rack-bank">racks</a>):</p><ul><li>Occupied <strong>Select</strong> starts (or continues) a morph <strong>live → that pad</strong> when <strong>this bank&#39;s FADE TIME</strong> is on. When <strong>this bank&#39;s FADE TIME</strong> is <strong>OFF</strong>, occupied Select lands instantly.</li><li><strong>Hold Select and turn the encoder</strong> on an occupied <strong>BANK</strong> pad to arm a morph from what you are hearing to that pad at <strong>0%</strong>. The first click arms <strong>and</strong> moves the blend. After a short hold the header mark becomes a circle and square so you can see that this hold is a blend, not a tap. This works with fade <strong>OFF</strong> (the clocked glide does not start). While a glide is already running, hold Select and turn still rides the amount. Turning past <strong>100%</strong> does not wrap back to 0% on the same hold, and 100% stays armed so you can turn back. Opening pad <strong>Options</strong> (keep holding Select) uses the encoder for the menu — it does not morph. Let go below 100% and the mix stays at that percent; hold Select and turn again to continue from there. Turn all the way back to <strong>0%</strong> and the morph ends.</li><li>Another occupied pad while a glide is running <strong>retargets</strong> — it ends the current glide and starts a new one from the live sound to the new pad. You do not confirm <strong>END + RECALL</strong>. With fade <strong>OFF</strong>, retarget the blend pad by holding Select and turning on a different occupied pad — a tap still lands instantly.</li><li>The <strong>same</strong> pad you are already morphing toward does not restart a glide.</li><li>Empty pads <strong>TAKE</strong> (or dest-pick). They do not morph.</li><li><strong>Back</strong> only leaves the screen. A morph keeps its percent. To end a morph, turn it back to <strong>0%</strong>.</li></ul><p>While a morph is running, the <strong>pad you are blending toward</strong> shows a <strong>fader and percent as one group</strong> (after the pad number, with a little air from the index). Live is the near end; that pad is the far end. The header stays <strong>Knobs Snapshots</strong>. The fader stays the same width from <strong>0%</strong> to <strong>100%</strong> — only the percent text changes. The group hides about a second and a half after you stop turning, or after a mapped morph knob stops moving. Hold Select and turn again to continue from the last percent, including at <strong>100%</strong>. Let go at 100% and that pad becomes the live snapshot. Arrange SONG still marks that column <code>K*</code> / <code>L*</code> / <code>R1*</code>…<code>R8*</code>.</p><p><img src="'+c+'" alt="Knob snapshot 4×8 while morphing" class="screen"></p><h2 id="sweep-the-amount" tabindex="-1">Sweep the amount <a class="header-anchor" href="#sweep-the-amount" aria-label="Permalink to &quot;Sweep the amount&quot;">​</a></h2><p>While a morph is running (including a hold-arm at 100%), <strong>hold Select and turn the encoder</strong> on that 4×8. A slow turn moves about <strong>1%</strong>; turning faster takes larger steps (the same slow/fast encoder feel as other values). <strong>0%</strong> is your own sound. Touching a knob or a setting during a morph or fade keeps it where you put it — the morph stops moving it. <strong>100%</strong> is the target pad. Reaching 100% does <strong>not</strong> end the hold — turn back toward 0% to morph toward live again. Letting go at 100% lands the pad. Letting go below 100% keeps that percent so the next hold continues from there.</p><h2 id="back-to-0" tabindex="-1">Back to 0% <a class="header-anchor" href="#back-to-0" aria-label="Permalink to &quot;Back to 0%&quot;">​</a></h2><p>Turning a morph back to <strong>0%</strong> ends it — with the encoder, a mapped knob, or MIDI. You hear what you heard before the morph, plus anything you changed while it ran. Turn up again and a new morph starts from that sound, so a setting you changed joins in from where you left it. Nothing jumps.</p><h2 id="map-the-amount-to-a-knob" tabindex="-1">Map the amount to a knob <a class="header-anchor" href="#map-the-amount-to-a-knob" aria-label="Permalink to &quot;Map the amount to a knob&quot;">​</a></h2><p>You can also <strong>map the amount</strong> from a knob or from MIDI CC / 14-bit CC (<strong>SETTINGS → MAPPING → MAP MORPH</strong>). That mapping is a fader from <strong>your own sound</strong> at 0% to the <strong>current snapshot</strong> on that bank at 100% — the same idea as a crossfader between two tracks, for MIDI and the other snapshot fields. You do not have to start a pad glide first. Moving up from 0% starts the morph from what you are hearing. Turning back to 0% ends it. Recalling or taking a different snapshot aims the same fader at that scene. The mapping hub is titled <strong>MAP AMOUNT</strong> (Internal knob or External CC / 14-bit CC). Learn External with CC or 14-bit CC (not notes or a physical knob move). The mapped knob <strong>is</strong> the amount and always covers the full <strong>0–100%</strong>. On the macro grid a <strong>MORPH</strong> macro shows <strong>MODE</strong>, <strong>PART</strong>, and <strong>INVERT</strong> — there is no <strong>MIN</strong> or <strong>MAX</strong>. <strong>INVERT</strong> flips the knob so turning it down morphs up. <strong>PART</strong> reads <strong>KNOBS</strong>, <strong>LFOS</strong>, or <strong>RACK1</strong>…<strong>RACK8</strong>.</p><p><img src="'+m+'" alt="MORPH macro on the macro grid" class="screen"> Program Change and notes do not drive amount. An LFO cannot target morph amount (and still cannot target snapshot <strong>index</strong>). <strong>MAPPING → UNMAP MORPH</strong> removes that mapping.</p><p>Hold Select and turn on an occupied <strong>BANK</strong> pad still morphs toward <strong>that</strong> pad (a manual override). Empty banks do nothing.</p><p>A morph-amount knob is not rewritten when the knobs snapshot morphs or recalls — it stays the blend fader. It always picks up, so it never jumps the sound. The knob does nothing until you bring it to the percent on the screen: <strong>0%</strong> when nothing is morphing, or the current percent while a pad glide runs or after the encoder moved the morph. That includes right after loading a project with the knob away from 0%, and after a pad glide lands. An <a href="./lanes">Arrange</a> step on that bank does not wait for the knob either. It glides from what you hear, and the knob picks up again. While it waits, the percent is dim and a dotted line on the bar marks where to catch. Once you reach it, the percent is bright and the knob is the amount. A <strong>MORPH</strong> macro has no <strong>PICKUP</strong> row, and neither does a snapshot-slot macro.</p><p><img src="'+a+'" alt="Morph knob waiting to catch 0%" class="screen"></p><p>Pickup on other macros keeps the <strong>solid value line</strong> on the physical knob: <strong>dim</strong> until you catch, <strong>bright</strong> when you are in control. The <strong>dotted catch line</strong> is brighter. While an LFO is modulating that macro you can still catch when the mix is not moving; the LFO follows the catch as an offset. When the LFO sits on the catch, that LFO mark is dotted too.</p><p>A morph-amount macro on Perform reads <strong>MORPH</strong>, the bank (<strong>Knobs</strong>, <strong>LFOs</strong>, or the rack name), <strong>TO DROP</strong>, and <strong>42%</strong> on the right while that bank is morphing. Idle, the destination is the current snapshot on that bank and the percent reads <strong>0%</strong>. When only one or two macros are on, Perform gives it the taller layout — see <a href="./../perform/knob-view#snapshot-and-morph-knobs">Snapshot and morph knobs on Perform</a>.</p><p><img src="'+r+'" alt="Morph knob packed on Perform" class="screen"></p><h2 id="what-a-morph-moves" tabindex="-1">What a morph moves <a class="header-anchor" href="#what-a-morph-moves" aria-label="Permalink to &quot;What a morph moves&quot;">​</a></h2><ul><li><strong>0–49%:</strong> discrete fields and the whole Step Seq pattern stay on live (A).</li><li><strong>50–100%:</strong> those fields jump to the target pad.</li></ul><p>Continuous values move smoothly the whole way: pot positions, LFO rate / depth / phase / offset, and device parameters that have a real range (not enums, notes, or channels).</p><p>An LFO keeps running through the whole morph. Its wave keeps moving everything it modulates while its settings glide to the pad, and it arrives on the pad&#39;s phase without a jump. A recall with <strong>FADE TIME OFF</strong> starts each LFO&#39;s wave on its stored phase.</p><p>A macro, device, or LFO set to <strong>IN SNAPSHOT OFF</strong> stays where it is for the whole morph. That switch covers every snapshot. A <strong>MORPH</strong> or <strong>SNAPSHOT</strong> macro has no <strong>IN SNAPSHOT</strong> row and stays out of every snapshot. See <a href="./#one-switch-for-a-whole-macro-device-or-lfo">One switch for a whole macro, device, or LFO</a>.</p><p>A parameter set to <strong>IN SNAPSHOT OFF</strong> is skipped by a morph at <strong>every</strong> position, including the ends. That row is hidden while its device or LFO is <strong>OFF</strong>. See <a href="./#keep-one-parameter-under-your-hands">Keep one parameter under your hands</a>.</p><p>A parameter set to <strong>ALLOW MORPH NO</strong> (with <strong>IN SNAPSHOT ON</strong>) stays live during the fade and jumps to the snapshot at <strong>100%</strong>. It does not lerp.</p><p>MIDI is sent only when a value changes, using the same pickup rules as a recall: the morph output is the logical value; physical knobs still have to catch up.</p><p>The Step Seq <strong>playhead keeps running</strong>. Morphing does not emit a new note for every in-between pattern — the pattern swaps as a whole at 50%.</p><h2 id="fade-time" tabindex="-1">Fade Time <a class="header-anchor" href="#fade-time" aria-label="Permalink to &quot;Fade Time&quot;">​</a></h2><p><strong>FADE TIME</strong> on that bank’s <strong>pencil</strong> sets how a pad / MIDI / <strong>SNAPSHOT</strong> macro recall lerps into the target slot, in musical time at the project BPM: <strong>OFF</strong> (instant, default), then <strong>1/16</strong>, <strong>1/8</strong>, <strong>1/4</strong>, <strong>1/2</strong>, <strong>1 BAR</strong>, <strong>2 BARS</strong>, <strong>4 BARS</strong>. Hold Select and turn the encoder to change it. Arrange <strong>pencil → FADE TIME</strong> is only how the <strong>playhead</strong> glides — it does not change pad recalls.</p><ul><li>A recall from Main Menu Snapshots, a mapped slot, or a macro uses <strong>that bank’s</strong> FADE TIME. The Arrange <strong>playhead</strong> uses Arrange FADE TIME. Both glides start from what you are hearing when the fade arms, the same as encoder / MAP MORPH.</li><li>When <strong>this bank&#39;s FADE TIME</strong> is <strong>OFF</strong>, occupied Select is instant. You can still morph by holding Select and turning the encoder on that pad.</li><li>Take and delete on that bank wait until the fade finishes.</li><li><a href="./lanes">Arrange</a> <strong>Jump To</strong> and <strong>Queue</strong> stay instant. Jump To aborts an in-progress fade by snapping to the fade target, then jumps. Queue cancels the fade without snapping, then the queue can fire.</li></ul><p>A knob or MIDI mapping can still step a <strong>snapshot slot index</strong> (<strong>SETTINGS → MAPPING → MAP SNAPSHOT</strong>). <strong>MAP MORPH</strong> is the blend-amount mapping under the same <strong>MAPPING</strong> row — not a second destination pad.</p>',34)),l(n,null,{default:d(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"./knob-bank"},"Knob snapshots"),o(" — Occupied Select on the 4×8")]),t("li",null,[t("a",{href:"./rack-bank"},"Rack snapshots"),o(" — Morph from a rack pad")]),t("li",null,[t("a",{href:"./lfo-bank"},"LFO snapshots"),o(" — Morph from an LFO pad")]),t("li",null,[t("a",{href:"./lanes"},"Arrange"),o(" — Clocked recall; Jump To / Queue stay instant")]),t("li",null,[t("a",{href:"./"},"Snapshots"),o(" — Snapshot overview")])],-1)])]),_:1})])}const S=s(u,[["render",f]]);export{M as __pageData,S as default};
